#!/usr/bin/env python3"""Dependency-free, read-only reference adapter for a PAIOS Markdown vault."""import argparseimport jsonimport sysfrom pathlib import Pathdef parse_frontmatter(text):    """Return simple top-level frontmatter fields, or an empty dict."""    lines = text.splitlines()    if not lines or lines[0].strip() != "---":        return {}    data = {}    for line in lines[1:]:        if line.strip() == "---":            return data        if ":" in line:            key, value = line.split(":", 1)            data[key.strip()] = value.strip().strip("\"'")    return {}def entries(vault):    """Yield contained Markdown files only; never follow a symlink outside root."""    root = Path(vault).expanduser().resolve(strict=True)    if not root.is_dir():        raise NotADirectoryError(root)    for path in sorted(root.rglob("*.md")):        try:            resolved = path.resolve(strict=True)        except OSError:            continue        if not resolved.is_file() or not resolved.is_relative_to(root):            continue        yield path.relative_to(root), resolved.read_text(encoding="utf-8"), parse_frontmatter(resolved.read_text(encoding="utf-8"))def search(vault, query):    needle = query.casefold()    results = []    for relative, text, metadata in entries(vault):        if needle in text.casefold():            results.append({                "path": relative.as_posix(),                "id": metadata.get("id"),                "title": metadata.get("title"),                "snippet": " ".join(text.split())[:240],            })    print(json.dumps(results, ensure_ascii=False, indent=2))    return 0def read_entry(vault, identifier):    matches = []    for relative, text, metadata in entries(vault):        if metadata.get("id") == identifier:            matches.append((relative, text))    if not matches:        print("Not found", file=sys.stderr)        return 1    if len(matches) > 1:        print("Ambiguous ID: " + identifier, file=sys.stderr)        return 2    print(matches[0][1], end="" if matches[0][1].endswith("\n") else "\n")    return 0def main(argv=None):    parser = argparse.ArgumentParser(description="Read-only PAIOS vault adapter")    parser.add_argument("vault")    commands = parser.add_subparsers(dest="command", required=True)    search_parser = commands.add_parser("search")    search_parser.add_argument("query")    read_parser = commands.add_parser("read")    read_parser.add_argument("id")    args = parser.parse_args(argv)    try:        if args.command == "search":            return search(args.vault, args.query)        return read_entry(args.vault, args.id)    except (FileNotFoundError, NotADirectoryError, UnicodeError) as error:        print("Adapter error: " + str(error), file=sys.stderr)        return 2if __name__ == "__main__":    raise SystemExit(main())
